LIMITS = {"spacing_min": 0.3, "spacing_max": 3.0, "duration_max": 300}


def validate(msg: dict) -> tuple:
    """车端自己也再校验一遍——设备端的安全检查不能当成唯一防线。"""
    cmd = msg.get("cmd")
    if cmd not in VALID:
        return False, "未知命令 %r" % cmd
    if cmd == "START_FORMATION":
        sp = msg.get("spacing_m")
        if sp is not None:
            if sp < LIMITS["spacing_min"]:
                return False, "间距 %.2f m 低于车端最小安全间距 %.2f m" % (sp, LIMITS["spacing_min"])
            if sp > LIMITS["spacing_max"]:
                return False, "间距 %.2f m 超过车端上限 %.2f m" % (sp, LIMITS["spacing_max"])
        du = msg.get("duration_s")
        if du is not None and (du <= 0 or du > LIMITS["duration_max"]):
            return False, "时长 %.1f s 不合法" % du
        if not msg.get("formation"):
            return False, "缺 formation"
    return True, "ok"


def load_mapping(path: str) -> dict:
